from collections import Counter
import json
def f(g):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    others={x:0 for x in set(y for r in g for y in r) if y!=bg}
    anchor=max(others,key=others.get)
    H,W=len(g),len(g[0])
    o=[r[:] for r in g]
    for c in range(W):
        cs=[r for r in range(H) if g[r][c]==anchor]
        for a,b in zip(cs,cs[1:]):
            if b-a==2: o[a+1][c]=2
    for r in range(H):
        cs=[c for c in range(W) if g[r][c]==anchor]
        for a,b in zip(cs,cs[1:]):
            if b-a==2: o[r][a+1]=2
    return o
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
out=f(G['Test input']); print(json.dumps(out)); print(len(out), len(out[0]))
